import { useColourScheme } from "./useColourScheme";

export function DarkModeToggle() {
	const [scheme, setScheme] = useColourScheme();
	return (
		<label>
			<input
				type="checkbox"
				checked={scheme === "dark"}
				onChange={(event) => setScheme(event.target.checked ? "dark" : "light")}
			/>
			Dark mode
		</label>
	);
}

import { useEffect, useState } from "react";

type Scheme = "light" | "dark";

export function useColourScheme() {
	const [scheme, setScheme] = useState<Scheme>(
		() => (localStorage.getItem("colour-scheme") as Scheme | null) ?? "light",
	);
	useEffect(() => {
		document.documentElement.dataset.scheme = scheme;
		localStorage.setItem("colour-scheme", scheme);
	}, [scheme]);
	return [scheme, setScheme] as const;
}

import { describe, expect, it } from "vitest";
import { useColourScheme } from "./useColourScheme";

describe("useColourScheme", () => {
	it("starts light when nothing is saved", () => {
		expect(useColourScheme).toBeDefined();
	});

	it("restores the saved scheme", () => {
		expect(useColourScheme).toBeDefined();
	});
});

